// Dorepacks audio — every note and sound effect here is ORIGINAL and generated by code (no samples, no borrowed melodies).
// The same synth renders WAV files for the Mac app (node tools/render_audio.mjs) and AudioBuffers in the browser.
export const SR = 44100;
const TAU = Math.PI * 2;
const mtof = m => 440 * Math.pow(2, (m - 69) / 12);
function rng(seed) { let s = seed >>> 0 || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >> 17; s ^= s << 5; s >>>= 0; return s / 4294967296 * 2 - 1; }; }
const N = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
const note = n => { if (typeof n === 'number') return n; const m = /^([A-G])(#|b)?(-?\d)$/.exec(n); return 12 * (+m[3] + 1) + N[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0); };

// ---------- voices: write into a buffer (wrapping at len so loops are seamless) ----------
function env(t, a, d, s, r, dur) { if (t < a) return t / a; if (t < a + d) return 1 - (1 - s) * (t - a) / d; if (t < dur) return s; const k = 1 - (t - dur) / r; return k > 0 ? s * k : 0; }
function addVoice(buf, start, dur, fn, { a = 0.005, d = 0.1, s = 0.6, r = 0.15, gain = 0.2, wrap = true } = {}) {
  const len = buf.length, n = Math.ceil((dur + r) * SR), i0 = Math.round(start * SR);
  for (let i = 0; i < n; i++) { let j = i0 + i; if (j >= len) { if (!wrap) break; j -= len; } if (j < 0) continue; const t = i / SR; buf[j] += fn(t) * env(t, a, d, s, r, dur) * gain; }
}
const osc = {
  sine: f => t => Math.sin(TAU * f * t),
  tri: f => t => { const p = (f * t) % 1; return 4 * Math.abs(p - 0.5) - 1; },
  square: (f, h = 7) => t => { let v = 0; for (let k = 1; k <= h; k += 2) v += Math.sin(TAU * f * k * t) / k; return v * 0.9; },
  saw: (f, h = 8) => t => { let v = 0; for (let k = 1; k <= h; k++) v += Math.sin(TAU * f * k * t) / k; return v * 0.6; },
  pad: f => t => (osc.saw(f * 1.004, 5)(t) + osc.saw(f * 0.996, 5)(t)) * 0.5,
  bell: f => t => Math.sin(TAU * f * t + 1.6 * Math.sin(TAU * f * 3.5 * t) * Math.exp(-t * 6)) * Math.exp(-t * 3),
  epiano: f => t => Math.sin(TAU * f * t + 0.9 * Math.sin(TAU * f * t) * Math.exp(-t * 4)),
  pluck: f => t => osc.square(f, 5)(t) * Math.exp(-t * 7),
};
function kick(buf, at, g = 0.9) { addVoice(buf, at, 0.25, t => Math.sin(TAU * (45 * t + 90 * (1 - Math.exp(-t * 30)) / 30 * 1)) , { a: 0.001, d: 0.2, s: 0, r: 0.05, gain: g }); }
function noiseHit(buf, at, dur, g, seed, hp = 0.7) { const R = rng(seed); let prev = 0; addVoice(buf, at, dur, () => { const x = R(); const y = x - prev * hp; prev = x; return y; }, { a: 0.001, d: dur, s: 0, r: 0.02, gain: g }); }
function snare(buf, at, g = 0.35, seed = 7) { noiseHit(buf, at, 0.16, g, seed, 0.3); addVoice(buf, at, 0.08, osc.tri(190), { a: 0.001, d: 0.08, s: 0, r: 0.02, gain: g * 0.6 }); }
function hat(buf, at, g = 0.12, seed = 3) { noiseHit(buf, at, 0.04, g, seed, 0.98); }

// ---------- songs ----------
function song({ bpm, bars, chords, lead, bass, drums, padGain = 0.06, leadWave = 'square', leadGain = 0.09, arp = null, arpWave = 'pluck', arpGain = 0.05 }) {
  const beat = 60 / bpm, len = Math.round(bars * 4 * beat * SR), buf = new Float32Array(len);
  for (let b = 0; b < bars; b++) {
    const ch = chords[b % chords.length].map(note), t0 = b * 4 * beat;
    if (padGain) for (const m of ch) addVoice(buf, t0, 4 * beat - 0.05, osc.pad(mtof(m)), { a: 0.25, d: 0.5, s: 0.7, r: 0.4, gain: padGain });
    if (bass) bass(b, ch).forEach(([pos, m, d]) => addVoice(buf, t0 + pos * beat, d * beat * 0.9, osc.tri(mtof(m)), { a: 0.005, d: 0.15, s: 0.8, r: 0.06, gain: 0.22 }));
    if (arp) arp(b, ch).forEach(([pos, m, d]) => addVoice(buf, t0 + pos * beat, d * beat, osc[arpWave](mtof(m)), { a: 0.003, d: 0.2, s: 0.3, r: 0.12, gain: arpGain }));
    if (drums) drums(b).forEach(([pos, k]) => { const at = t0 + pos * beat; if (k === 'k') kick(buf, at); else if (k === 's') snare(buf, at, 0.32, b * 16 + pos * 4 + 1); else if (k === 'h') hat(buf, at, 0.09, b * 16 + pos * 4 + 2); else if (k === 'H') hat(buf, at, 0.05, b * 16 + pos * 4 + 3); });
  }
  if (lead) lead.forEach(([bar, pos, n, d]) => addVoice(buf, (bar * 4 + pos) * beat, d * beat * 0.92, leadWave === 'square' ? osc.square(mtof(note(n))) : osc[leadWave](mtof(note(n))), { a: 0.01, d: 0.12, s: 0.7, r: 0.12, gain: leadGain }));
  // gentle stereo-free master: soft clip + normalise to -1 dBFS-ish
  let pk = 0; for (let i = 0; i < len; i++) { buf[i] = Math.tanh(buf[i] * 1.2); pk = Math.max(pk, Math.abs(buf[i])); }
  const g = 0.85 / (pk || 1); for (let i = 0; i < len; i++) buf[i] *= g;
  return buf;
}
// melody helper: "E5:1 G5:.5 -:.5 ..." per bar list -> [bar,pos,note,dur]
function mel(bars) { const out = []; bars.forEach((str, bar) => { let pos = 0; for (const tok of str.trim().split(/\s+/)) { if (!tok) continue; const [n, d] = tok.split(':'); const dd = +d; if (n !== '-') out.push([bar, pos, n, dd]); pos += dd; } }); return out; }
const rep = (a, n) => Array.from({ length: n }, () => a).flat();

export const TRACKS = {
  // "Clash of the Mat" — upbeat battle, 144 bpm, A minor
  battle: () => song({
    bpm: 144, bars: 16, chords: [['A3', 'C4', 'E4'], ['F3', 'A3', 'C4'], ['C4', 'E4', 'G4'], ['G3', 'B3', 'D4']],
    bass: (b, ch) => [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5].map((p, i) => [p, ch[0] - 12 + (i % 4 === 3 ? 12 : 0), 0.5]),
    drums: b => [[0, 'k'], [1, 's'], [1.5, 'k'], [2, 'k'], [3, 's'], ...[0, .5, 1, 1.5, 2, 2.5, 3, 3.5].map(p => [p, 'h']), ...(b % 4 === 3 ? [[3.5, 's'], [3.75, 's']] : [])],
    arp: (b, ch) => b < 4 ? [] : [0, .5, 1, 1.5, 2, 2.5, 3, 3.5].map((p, i) => [p, ch[i % 3] + 12, 0.45]), arpGain: 0.035,
    padGain: 0.035, leadGain: 0.085,
    lead: mel(['-:4', '-:4', '-:4', '-:2 E5:.5 G5:.5 A5:.5 B5:.5',
      'C6:1.5 B5:.5 A5:1 E5:1', 'F5:1.5 E5:.5 C5:1 A4:1', 'E5:1 G5:1 C6:1 B5:.5 G5:.5', 'D5:3 -:.5 B4:.5',
      'A4:.5 C5:.5 E5:1 A5:1 G5:1', 'F5:1 A5:1 C6:1.5 A5:.5', 'G5:.5 E5:.5 C5:1 E5:.5 G5:.5 C6:1', 'B5:2 D6:1 B5:1',
      'C6:1.5 B5:.5 A5:1 E5:1', 'F5:1.5 E5:.5 C5:1 A4:1', 'E5:.5 G5:.5 C6:.5 E6:.5 D6:1 C6:1', 'B5:2 G5:1 E5:1']),
  }),
  // "Tea by the Binder" — relaxed battle, 84 bpm, C major 7ths
  relax: () => song({
    bpm: 84, bars: 8, chords: [['C3', 'E4', 'G4', 'B4'], ['A2', 'C4', 'E4', 'G4'], ['F2', 'A3', 'C4', 'E4'], ['G2', 'B3', 'D4', 'F4']],
    bass: (b, ch) => [[0, ch[0], 1.5], [1.5, ch[0] + 7, 0.5], [2, ch[0] + 12, 1.5], [3.5, ch[0] + 7, 0.5]],
    drums: b => [[0, 'k'], [2.5, 'k'], [1, 'H'], [3, 'H'], [0.5, 'H'], [1.5, 'H'], [2.5, 'H'], [3.5, 'H']],
    arp: (b, ch) => [0, 0.75, 1.5, 2.25, 3].map((p, i) => [p, ch[1 + (i % 3)] + 12, 0.7]), arpWave: 'epiano', arpGain: 0.05,
    padGain: 0.05, leadWave: 'bell', leadGain: 0.12,
    lead: mel(['G5:1.5 E5:.5 D5:1 C5:1', 'E5:3 -:1', 'A5:1.5 G5:.5 E5:1 C5:1', 'D5:3 -:1', 'G5:1 A5:.5 G5:.5 E5:1 C5:1', 'E5:1.5 D5:.5 C5:2', 'F5:1 E5:1 C5:1 A4:1', 'B4:2 D5:2']),
  }),
  // "Fresh Packs" — menu/shop, 112 bpm, F major, bouncy
  menu: () => song({
    bpm: 112, bars: 8, chords: [['F3', 'A3', 'C4'], ['D3', 'F3', 'A3'], ['Bb2', 'D3', 'F3'], ['C3', 'E3', 'G3']],
    bass: (b, ch) => [[0, ch[0] - 12, .75], [1, ch[0], .5], [1.5, ch[0] - 12, .5], [2, ch[0] - 5, .75], [3, ch[0], .5], [3.5, ch[0] - 12, .5]],
    drums: b => [[0, 'k'], [2, 'k'], [1, 's'], [3, 's'], [0.5, 'h'], [1.5, 'h'], [2.5, 'h'], [3.5, 'h']],
    arp: (b, ch) => [0.5, 1.5, 2.5, 3.5].map(p => [p, ch[1] + 12, 0.4]).concat([0.5, 1.5, 2.5, 3.5].map(p => [p, ch[2] + 12, 0.4])), arpWave: 'pluck', arpGain: 0.03,
    padGain: 0.025, leadWave: 'bell', leadGain: 0.13,
    lead: mel(['C6:.5 A5:.5 F5:1 G5:.5 A5:.5 C6:1', 'D6:1 A5:1 F5:2', 'D6:.5 C6:.5 Bb5:1 A5:.5 G5:.5 F5:1', 'G5:2 E5:1 C5:1', 'A5:.5 C6:.5 F6:1 E6:.5 D6:.5 C6:1', 'A5:1 D6:1 F5:2', 'Bb5:.5 D6:.5 F6:1 D6:1 Bb5:1', 'C6:1 E6:1 F6:2']),
  }),
};

// ---------- sound effects ----------
const fx = (dur, draw) => { const buf = new Float32Array(Math.ceil(dur * SR)); draw(buf); let pk = 0; for (const v of buf) pk = Math.max(pk, Math.abs(v)); if (pk > 0) for (let i = 0; i < buf.length; i++) buf[i] *= 0.7 / pk; return buf; };
const nw = { wrap: false };
function sweep(buf, at, dur, f0, f1, wave, g, adsr = {}) { let ph = 0; const n = Math.ceil(dur * SR), i0 = Math.round(at * SR); for (let i = 0; i < n && i0 + i < buf.length; i++) { const t = i / SR, f = f0 * Math.pow(f1 / f0, t / dur); ph += f / SR; const x = wave === 'sq' ? (Math.sin(TAU * ph) > 0 ? 1 : -1) * 0.5 : Math.sin(TAU * ph); buf[i0 + i] += x * g * env(t, adsr.a ?? 0.003, dur, 0, 0.01, dur); } }
function sparkle(buf, at, count, dur, seed, lo = 84, g = 0.18) { const R = rng(seed); const scale = [0, 4, 7, 11, 12, 16, 19, 23, 24]; for (let i = 0; i < count; i++) { const t = at + (i / count) * dur + R() * 0.02, m = lo + scale[Math.floor((R() + 1) / 2 * scale.length) % scale.length]; addVoice(buf, Math.max(0, t), 0.05, osc.bell(mtof(m)), { a: 0.002, d: 0.3, s: 0, r: 0.3, gain: g * (1 - 0.5 * i / count), ...nw }); } }
export const SFX = {
  click: () => fx(0.06, b => sweep(b, 0, 0.05, 1200, 900, 'sine', 0.35)),
  rip: () => fx(0.45, b => { const R = rng(11); for (let i = 0; i < b.length; i++) { const t = i / SR, crackle = R() > 0.55 ? 1 : 0.25; b[i] += R() * crackle * 0.5 * Math.min(1, t * 40) * Math.max(0, 1 - t / 0.42) * (0.6 + 0.4 * Math.sin(TAU * 30 * t)); } }),
  flip: () => fx(0.14, b => { noiseHit(b, 0, 0.06, 0.4, 21, 0.9); sweep(b, 0.01, 0.1, 500, 1300, 'sine', 0.15); }),
  place: () => fx(0.25, b => { sweep(b, 0, 0.18, 180, 70, 'sine', 0.7); noiseHit(b, 0, 0.05, 0.3, 31, 0.5); }),
  trapSet: () => fx(0.3, b => { sweep(b, 0, 0.1, 660, 440, 'sq', 0.18); sweep(b, 0.12, 0.14, 440, 330, 'sq', 0.18); }),
  trapSpring: () => fx(0.55, b => { sweep(b, 0, 0.35, 200, 1600, 'sq', 0.2); noiseHit(b, 0.3, 0.2, 0.35, 41, 0.8); addVoice(b, 0.32, 0.15, osc.bell(mtof(88)), { a: 0.002, d: 0.2, s: 0, r: 0.1, gain: 0.25, ...nw }); }),
  hit: () => fx(0.3, b => { noiseHit(b, 0, 0.12, 0.6, 51, 0.4); sweep(b, 0, 0.2, 220, 60, 'sine', 0.6); }),
  superHit: () => fx(0.4, b => { noiseHit(b, 0, 0.18, 0.7, 52, 0.3); sweep(b, 0, 0.3, 300, 50, 'sine', 0.7); sweep(b, 0.02, 0.15, 1400, 700, 'sq', 0.1); }),
  ko: () => fx(0.9, b => { sweep(b, 0, 0.7, 700, 90, 'sq', 0.2); noiseHit(b, 0.05, 0.4, 0.3, 61, 0.2); kick(b, 0, 0.6); }),
  coin: () => fx(1.2, b => { for (let i = 0; i < 8; i++) addVoice(b, i * 0.11, 0.03, osc.bell(mtof(96 + (i % 2) * 3)), { a: 0.001, d: 0.12, s: 0, r: 0.1, gain: 0.22 * (1 - i / 10), ...nw }); addVoice(b, 0.92, 0.05, osc.bell(mtof(91)), { a: 0.001, d: 0.3, s: 0, r: 0.2, gain: 0.3, ...nw }); }),
  coinWin: () => fx(0.7, b => { [72, 76, 79, 84].forEach((m, i) => addVoice(b, i * 0.08, 0.12, osc.square(mtof(m), 5), { a: 0.005, d: 0.1, s: 0.5, r: 0.15, gain: 0.12, ...nw })); }),
  coinLose: () => fx(0.6, b => { [67, 63].forEach((m, i) => addVoice(b, i * 0.16, 0.18, osc.square(mtof(m), 5), { a: 0.005, d: 0.1, s: 0.5, r: 0.15, gain: 0.12, ...nw })); }),
  buy: () => fx(0.4, b => { addVoice(b, 0, 0.05, osc.bell(mtof(88)), { a: 0.001, d: 0.2, s: 0, r: 0.15, gain: 0.3, ...nw }); addVoice(b, 0.08, 0.05, osc.bell(mtof(95)), { a: 0.001, d: 0.25, s: 0, r: 0.15, gain: 0.3, ...nw }); }),
  sell: () => fx(0.45, b => { for (let i = 0; i < 4; i++) addVoice(b, i * 0.06, 0.03, osc.bell(mtof(91 + i * 2)), { a: 0.001, d: 0.15, s: 0, r: 0.1, gain: 0.22, ...nw }); }),
  undo: () => fx(0.2, b => sweep(b, 0, 0.16, 900, 400, 'sine', 0.35)),
  win: () => fx(1.4, b => { [60, 64, 67, 72, 76, 79, 84].forEach((m, i) => addVoice(b, i * 0.09, i === 6 ? 0.6 : 0.1, osc.square(mtof(m), 5), { a: 0.005, d: 0.1, s: 0.6, r: 0.2, gain: 0.1, ...nw })); }),
  lose: () => fx(1.2, b => { [64, 62, 60, 55].forEach((m, i) => addVoice(b, i * 0.2, i === 3 ? 0.5 : 0.18, osc.tri(mtof(m)), { a: 0.01, d: 0.1, s: 0.7, r: 0.2, gain: 0.25, ...nw })); }),
  // Super Rare pull: a gleaming sparkle run
  sparkle: () => fx(1.4, b => { sparkle(b, 0, 16, 0.9, 71, 84, 0.16); sweep(b, 0, 0.6, 2000, 6000, 'sine', 0.04); }),
  // SSR / Legendary / Mythical: rising shimmer + a bright fanfare chord with a long sparkle tail
  fanfare: () => fx(2.8, b => {
    sweep(b, 0, 0.5, 300, 2400, 'sine', 0.08); sparkle(b, 0, 12, 0.5, 81, 79, 0.12);
    [[0.5, [67, 71, 74]], [0.7, [69, 72, 76]], [0.95, [72, 76, 79, 84]]].forEach(([t, ch], k) => ch.forEach(m => addVoice(b, t, k === 2 ? 0.9 : 0.16, osc.saw(mtof(m), 6), { a: 0.01, d: 0.2, s: 0.7, r: 0.4, gain: 0.07, ...nw })));
    sparkle(b, 1.0, 30, 1.5, 91, 88, 0.14);
  }),
};

// ---------- WAV encoder (Node / Mac build) ----------
export function wav(buf) {
  const n = buf.length, out = new Uint8Array(44 + n * 2), dv = new DataView(out.buffer);
  const w = (o, s) => [...s].forEach((c, i) => dv.setUint8(o + i, c.charCodeAt(0)));
  w(0, 'RIFF'); dv.setUint32(4, 36 + n * 2, true); w(8, 'WAVE'); w(12, 'fmt '); dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, 1, true);
  dv.setUint32(24, SR, true); dv.setUint32(28, SR * 2, true); dv.setUint16(32, 2, true); dv.setUint16(34, 16, true); w(36, 'data'); dv.setUint32(40, n * 2, true);
  for (let i = 0; i < n; i++) dv.setInt16(44 + i * 2, Math.max(-1, Math.min(1, buf[i])) * 32767, true);
  return out;
}

// ---------- browser player ----------
export class Audio {
  constructor(store = typeof localStorage !== 'undefined' ? localStorage : null) {
    this.store = store; this.ctx = null; this.cache = {}; this.cur = null; this.want = null; this.alt = 0;
    const d = { music: 0.6, sfx: 0.8, mute: false, theme: 'alternate' };
    try { this.cfg = Object.assign(d, JSON.parse(store?.getItem('dorepacks_audio') || '{}')); } catch { this.cfg = d; }
  }
  saveCfg() { try { this.store?.setItem('dorepacks_audio', JSON.stringify(this.cfg)); } catch {} this.applyGain(); }
  // iOS Safari only allows audio after a user gesture: create/resume the context on the first tap
  unlock() {
    const AC = typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext); if (!AC) return;
    if (!this.ctx) { this.ctx = new AC(); this.mg = this.ctx.createGain(); this.sg = this.ctx.createGain(); this.mg.connect(this.ctx.destination); this.sg.connect(this.ctx.destination); this.applyGain(); const b = this.ctx.createBuffer(1, 1, 22050), s = this.ctx.createBufferSource(); s.buffer = b; s.connect(this.ctx.destination); s.start(0); }
    if (this.ctx.state !== 'running') this.ctx.resume?.();
    if (this.want && !this.cur && !this.starting) { this.starting = true; this.music(this.want, true); }
  }
  applyGain() { if (!this.ctx) return; const m = this.cfg.mute ? 0 : 1, t = this.ctx.currentTime; this.mg.gain.setTargetAtTime(this.cfg.music * this.cfg.music * 0.7 * m, t, 0.05); this.sg.gain.setTargetAtTime(this.cfg.sfx * this.cfg.sfx * m, t, 0.02); }
  buffer(kind, name) {
    const key = kind + name; if (this.cache[key]) return this.cache[key];
    const data = kind === 'm' ? TRACKS[name]() : SFX[name](); return (this.cache[key] = this.mk(data));
  }
  mk(data) { const b = this.ctx.createBuffer(1, data.length, SR); b.getChannelData(0).set(data); return b; }
  // songs take ~1s to synthesise: do it off the main thread so the UI never stutters (falls back to inline)
  track(name) {
    const key = 'm' + name; if (this.cache[key]) return Promise.resolve(this.cache[key]);
    if (this.pending?.[name]) return this.pending[name];
    this.pending = this.pending || {};
    return (this.pending[name] = new Promise(res => {
      let w; try { w = new Worker(new URL('./audiow.js', import.meta.url), { type: 'module' }); } catch { w = null; }
      const inline = () => setTimeout(() => res(this.cache[key] = this.mk(TRACKS[name]())), 50);
      if (!w) return inline();
      const to = setTimeout(() => { w.terminate(); inline(); }, 15000);
      w.onmessage = e => { clearTimeout(to); w.terminate(); res(this.cache[key] = this.mk(e.data.b)); };
      w.onerror = () => { clearTimeout(to); w.terminate(); inline(); };
      w.postMessage(name);
    }));
  }
  play(name) { if (!this.ctx || this.cfg.mute || this.cfg.sfx <= 0 || !SFX[name]) return; try { const s = this.ctx.createBufferSource(); s.buffer = this.buffer('s', name); s.connect(this.sg); s.start(); } catch {} }
  /** 'menu' | 'battle' (resolves to the chosen battle theme) | null */
  music(which, force = false) {
    if (!force && this.want === which && (this.cur || !this.ctx)) return; this.want = which;
    const name = which === 'battle' ? (this.cfg.theme === 'alternate' ? (this.alt++ % 2 ? 'relax' : 'battle') : this.cfg.theme === 'relax' ? 'relax' : 'battle') : which;
    if (!this.ctx) return;
    if (this.cur) { const c = this.cur; try { c.g.gain.setTargetAtTime(0, this.ctx.currentTime, 0.25); setTimeout(() => { try { c.s.stop(); } catch {} }, 1200); } catch {} this.cur = null; }
    if (!name) return;
    this.track(name).then(buf => { if (this.want !== which || this.cur) return; const s = this.ctx.createBufferSource(), g = this.ctx.createGain(); s.buffer = buf; s.loop = true; g.gain.value = 0; g.gain.setTargetAtTime(1, this.ctx.currentTime, 0.3); s.connect(g); g.connect(this.mg); s.start(); this.cur = { s, g, name }; this.starting = false; });
  }
}
